(425, 11, 'Zachariah predicts that the Messiah would be betrayed for 20 pieces of silver.', 'TRUE', 'FALSE', '', '', '', 'FALSE', 0.00, '2017-01-20 03:35:03', '2017-01-19 20:35:03', 0, 0),
(426, 11, 'The final scene of Zechariah is the enthronement of the glorious King in splendor and glory.\r\n', 'TRUE', 'FALSE', '', '', '', 'TRUE', 0.00, '2017-01-20 03:35:03', '2017-01-19 20:35:03', 0, 0),
(427, 11, 'Joel\\\'s name means \\\"Jehovah is God.\\\"', 'TRUE', 'FALSE', '', '', '', 'TRUE', 0.00, '2017-01-20 03:35:03', '2017-01-19 20:35:03', 0, 0),
(428, 11, 'Joel talked about the Day of the Lord in his book.', 'TRUE', 'FALSE', '', '', '', 'TRUE', 0.00, '2017-01-20 03:35:03', '2017-01-19 20:35:03', 0, 0),
