(430, 11, 'Joel predicted the coming of the outpouring of the Holy Spirit in the last days.', 'TRUE', 'FALSE', '', '', '', 'TRUE', 0.00, '2017-01-20 03:35:03', '2017-01-19 20:35:03', 0, 0),
(431, 11, 'Joel?s book ends with a prophecy of doom.\r\n', 'TRUE', 'FALSE', '', '', '', 'FALSE', 0.00, '2017-01-20 03:35:03', '2017-01-19 20:35:03', 0, 0),
